namespace docking.options.editor;



/**
 * A {@link PropertyEditor} that allows the user to edit strings by way of a File editor, as is
 * done by {@link StringBasedFileEditor}.  In other words, the user can use the file chooser to
 * pick a file.  That file is then turned into a String. 
 * 
 * <P>This class has the restriction that it will only 
 * take in {@link String} objects and will only give out {@link String} objects.
 */
public class StringBasedFileEditor : FileChooserEditor {

	/* @Override */
	public void setValue(object value) {
		if (!(value is string)) {
			throw new IllegalArgumentException("Editor only edits String objects!");
		}

		base.setValue(value);
	}

	/* @Override */
	public object getValue() {
		return getAsText();
	}
}
